"""Contract tests for the public FastAPI OpenAPI specification."""

from app.main import app


def test_task_update_openapi_contract():
    """Ensure PATCH documentation matches runtime validation."""

    # Generate the actual OpenAPI document exposed by FastAPI.
    # No running HTTP server or database connection is required.
    document = app.openapi()

    # Retrieve the reusable schemas generated by FastAPI.
    schemas = document["components"]["schemas"]
    schema = schemas["TaskUpdate"]
    properties = schema["properties"]

    # Verify that the PATCH endpoint references TaskUpdate
    # as its public JSON request body contract.
    patch_operation = document["paths"]["/api/tasks/{task_id}"]["patch"]

    request_schema = patch_operation["requestBody"]["content"][
        "application/json"
    ]["schema"]

    assert request_schema["$ref"] == (
        "#/components/schemas/TaskUpdate"
    )

    # Verify that all expected update fields are documented.
    assert set(properties) == {
        "title",
        "description",
        "status",
    }

    # PATCH fields must be optional because callers can
    # update individual properties independently.
    assert not schema.get("required", [])

    # Preserve title validation constraints.
    assert properties["title"]["type"] == "string"
    assert properties["title"]["minLength"] == 1
    assert properties["title"]["maxLength"] == 120

    # Preserve description validation constraints.
    assert properties["description"]["type"] == "string"
    assert properties["description"]["maxLength"] == 1000

    # Ensure that the status field references the shared enum.
    assert properties["status"]["$ref"] == (
        "#/components/schemas/TaskStatus"
    )

    # API-001 regression protection:
    # Fields may be omitted but must not advertise null
    # as an accepted value or a documented default.
    for definition in properties.values():
        assert "anyOf" not in definition
        assert "default" not in definition
        assert definition.get("nullable") is not True

    # Preserve the supported Kanban workflow stages.
    assert schemas["TaskStatus"]["type"] == "string"

    assert schemas["TaskStatus"]["enum"] == [
        "todo",
        "in_progress",
        "done",
    ]

    # Invalid request bodies must have a documented
    # HTTP 422 validation error response.
    assert "422" in patch_operation["responses"]
